#stage { --ground:#f7f2e8; --main:#20402f; --second:#e3a53c; --accent:#c2562b; color:var(--main); font-family:var(--sans, system-ui, sans-serif);
  --deep:color-mix(in srgb, var(--main) 78%, black); --moss:color-mix(in srgb, var(--main) 58%, var(--ground)); --fog:color-mix(in srgb, var(--ground) 84%, var(--main));
  --glow:color-mix(in srgb, var(--second) 45%, var(--ground)); --peach:color-mix(in srgb, var(--accent) 30%, var(--ground)); --amber:color-mix(in srgb, var(--accent) 45%, var(--second));
  --brew:color-mix(in srgb, var(--accent) 45%, var(--deep)); --clay:color-mix(in srgb, var(--accent) 86%, var(--ground)); --clay-shade:color-mix(in srgb, var(--accent) 66%, var(--deep));
  --wood:color-mix(in srgb, var(--second) 50%, var(--ground)); --steel:color-mix(in srgb, var(--ground) 62%, var(--main)); --steam:color-mix(in srgb, var(--ground) 80%, white);
  --hill-far:color-mix(in srgb, var(--main) 36%, var(--ground)); --hill-mid:color-mix(in srgb, var(--main) 64%, var(--ground)); --hill-near:var(--main); --mist:var(--ground) }
.ground { position:absolute; inset:0; background:var(--ground); overflow:hidden }
.art { position:absolute; inset:0; width:100%; height:100%; overflow:visible }
.sky-night { position:absolute; inset:0; background:linear-gradient(var(--deep), var(--main) 40%, color-mix(in srgb, var(--main) 72%, var(--ground)) 70%) }
.sky-low { position:absolute; inset:0; background:radial-gradient(75% 62% at 81% 70%, var(--peach), var(--glow) 34%, transparent 72%) }
.sky-day { position:absolute; inset:0; background:linear-gradient(var(--glow), var(--ground) 52%, var(--peach) 76%) }
.halo { position:absolute; left:0; top:0; width:1200px; height:1200px; border-radius:50%; background:radial-gradient(closest-side, color-mix(in srgb, var(--second) 60%, transparent), color-mix(in srgb, var(--second) 22%, transparent) 45%, transparent) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:26px } .words > * { margin:0 }
.line { font-family:var(--display, var(--sans, system-ui, sans-serif)); font-size:150px; line-height:1.02; font-weight:600; letter-spacing:-0.015em }
.sub { font-size:42px; line-height:1.3; font-weight:500 } .eyebrow { font-size:30px; line-height:1.2; font-weight:600; letter-spacing:0.2em; text-transform:uppercase }
